hl.bind(mainMod .. " + CTRL + up",    hl.dsp.window.resize({ x = 0, y = 40,  relative = true }), { repeating = true })
hl.bind(mainMod .. " + CTRL + down",  hl.dsp.window.resize({ x = 0, y = -40, relative = true }), { repeating = true })

