---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

-- Flameshot 13: span ASUS 2560x1440 + LG 1920x1080 at (2560,180).
hl.window_rule({
    name = "flameshot-multi-display",
    match = { class = "^flameshot$", title = "^flameshot$" },
    float = true,
    pin = true,
    no_anim = true,
    rounding = 0,
    border_size = 0,
    no_blur = true,
    no_shadow = true,
    fullscreen_state = "0 0",
    monitor = "DP-1",
    move = { 0, 0 },
    size = { 4480, 1440 },
})

-- Looking Glass stays on the LG 1080p monitor; fullscreen is user-controlled.
hl.window_rule({
    name       = "looking-glass-on-lg",
    match      = { class = "looking-glass-client" },
    monitor    = "DP-3",
})

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

